create extension if not exists pgcrypto;
create type public.app_role as enum ('admin');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique, role public.app_role not null, created_at timestamptz not null default now());
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy roles_self_read on public.user_roles for select to authenticated using (user_id = (select auth.uid()));
create function public.has_role(_user_id uuid, _role public.app_role) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.user_roles where user_id = _user_id and role = _role) $$;
grant execute on function public.has_role(uuid, public.app_role) to authenticated;
create table public.stores (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, logo_url text, website text, affiliate_template text, active boolean not null default true, trust_score numeric(5,2) not null default 50, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select, insert, update, delete on public.stores to authenticated; grant all on public.stores to service_role; alter table public.stores enable row level security; create policy stores_admin on public.stores for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, brand text, model text, ean text, category text, image_url text, active boolean not null default true, popularity_score numeric(5,2) not null default 50, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select, insert, update, delete on public.products to authenticated; grant all on public.products to service_role; alter table public.products enable row level security; create policy products_admin on public.products for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.coupons (id uuid primary key default gen_random_uuid(), store_id uuid references public.stores(id) on delete cascade, code text not null, description text, discount_type text check (discount_type in ('percent','fixed','shipping')), discount_value numeric(12,2), minimum_purchase numeric(12,2), expires_at timestamptz, verified boolean not null default false, last_verified_at timestamptz, created_at timestamptz not null default now());
grant select, insert, update, delete on public.coupons to authenticated; grant all on public.coupons to service_role; alter table public.coupons enable row level security; create policy coupons_admin on public.coupons for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.product_offers (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, store_id uuid not null references public.stores(id) on delete cascade, url text not null, affiliate_url text, current_price numeric(12,2), original_price numeric(12,2), shipping_price numeric(12,2) not null default 0, installments text, in_stock boolean not null default true, coupon_id uuid references public.coupons(id) on delete set null, last_checked_at timestamptz, next_check_at timestamptz, active boolean not null default true, unique(product_id, store_id, url));
grant select, insert, update, delete on public.product_offers to authenticated; grant all on public.product_offers to service_role; alter table public.product_offers enable row level security; create policy product_offers_admin on public.product_offers for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.price_history (id bigserial primary key, product_offer_id uuid not null references public.product_offers(id) on delete cascade, price numeric(12,2) not null, shipping_price numeric(12,2) not null default 0, in_stock boolean not null default true, collected_at timestamptz not null default now());
grant select, insert, update, delete on public.price_history to authenticated; grant all on public.price_history to service_role; grant usage, select on sequence public.price_history_id_seq to authenticated; alter table public.price_history enable row level security; create policy price_history_admin on public.price_history for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create index idx_price_history_offer_time on public.price_history(product_offer_id, collected_at desc);
create table public.offer_scores (id bigserial primary key, product_offer_id uuid not null references public.product_offers(id) on delete cascade, score integer not null check (score between 0 and 100), avg_7d numeric(12,2), avg_30d numeric(12,2), avg_40d numeric(12,2), avg_90d numeric(12,2), median_40d numeric(12,2), low_40d numeric(12,2), low_90d numeric(12,2), percent_below_avg numeric(8,3), is_new_low boolean not null default false, classification text not null, reasons jsonb not null default '[]'::jsonb, calculated_at timestamptz not null default now());
grant select, insert, update, delete on public.offer_scores to authenticated; grant all on public.offer_scores to service_role; grant usage, select on sequence public.offer_scores_id_seq to authenticated; alter table public.offer_scores enable row level security; create policy offer_scores_admin on public.offer_scores for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.collection_jobs (id bigserial primary key, product_offer_id uuid not null references public.product_offers(id) on delete cascade, status text not null default 'pending' check (status in ('pending','processing','completed','failed')), priority integer not null default 50, attempts integer not null default 0, scheduled_at timestamptz not null default now(), started_at timestamptz, finished_at timestamptz, error text);
grant select, insert, update, delete on public.collection_jobs to authenticated; grant all on public.collection_jobs to service_role; grant usage, select on sequence public.collection_jobs_id_seq to authenticated; alter table public.collection_jobs enable row level security; create policy collection_jobs_admin on public.collection_jobs for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create index idx_collection_jobs_queue on public.collection_jobs(status, priority desc, scheduled_at asc);
create table public.workers (id uuid primary key default gen_random_uuid(), name text not null unique, status text not null default 'offline', last_heartbeat timestamptz, processed_count bigint not null default 0, error_count bigint not null default 0, avg_duration_ms integer not null default 0, metadata jsonb not null default '{}'::jsonb);
grant select, insert, update, delete on public.workers to authenticated; grant all on public.workers to service_role; alter table public.workers enable row level security; create policy workers_admin on public.workers for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.telegram_channels (id uuid primary key default gen_random_uuid(), name text not null, chat_id text not null unique, active boolean not null default true, min_score integer not null default 75, allowed_categories text[] not null default '{}');
grant select, insert, update, delete on public.telegram_channels to authenticated; grant all on public.telegram_channels to service_role; alter table public.telegram_channels enable row level security; create policy telegram_channels_admin on public.telegram_channels for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.telegram_posts (id bigserial primary key, product_offer_id uuid references public.product_offers(id) on delete set null, channel_id uuid references public.telegram_channels(id) on delete cascade, telegram_message_id text, status text not null default 'pending', price numeric(12,2), score integer, payload jsonb not null default '{}'::jsonb, error text, created_at timestamptz not null default now(), sent_at timestamptz);
grant select, insert, update, delete on public.telegram_posts to authenticated; grant all on public.telegram_posts to service_role; grant usage, select on sequence public.telegram_posts_id_seq to authenticated; alter table public.telegram_posts enable row level security; create policy telegram_posts_admin on public.telegram_posts for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.collector_logs (id bigserial primary key, level text not null default 'info', event text not null, source text, product_offer_id uuid references public.product_offers(id) on delete set null, message text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
grant select, insert, update, delete on public.collector_logs to authenticated; grant all on public.collector_logs to service_role; grant usage, select on sequence public.collector_logs_id_seq to authenticated; alter table public.collector_logs enable row level security; create policy collector_logs_admin on public.collector_logs for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create table public.settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
grant select, insert, update, delete on public.settings to authenticated; grant all on public.settings to service_role; alter table public.settings enable row level security; create policy settings_admin on public.settings for all to authenticated using (public.has_role((select auth.uid()), 'admin')) with check (public.has_role((select auth.uid()), 'admin'));
create function public.touch_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = now(); return new; end $$;
create trigger stores_touch before update on public.stores for each row execute function public.touch_updated_at();
create trigger products_touch before update on public.products for each row execute function public.touch_updated_at();
create function public.record_offer_price_change() returns trigger language plpgsql security definer set search_path = '' as $$ begin if old.current_price is distinct from new.current_price and new.current_price is not null then insert into public.price_history(product_offer_id, price, shipping_price, in_stock) values (new.id, new.current_price, new.shipping_price, new.in_stock); end if; return new; end $$;
create trigger offer_price_changed after update on public.product_offers for each row execute function public.record_offer_price_change();